"""Casos redactados para la especificación; no son resultados de ejecución."""
CASES = {}
def case(hu, title, criteria, data, steps, expected, pre='Datos ficticios aislados; restaurar F-BASE antes del caso. Rol indicado autenticado salvo prueba de ingreso.'):
    CASES.setdefault(hu, []).append(dict(title=title, criteria=criteria, preconditions=pre, data=data, steps=steps.split(' || '), expected=expected))

# Cada conjunto de ordinales remite a la HU indicada. Las variantes se ejecutan de forma independiente.
case('HU-AUTH-01','Ingreso correcto de los tres roles',[1], 'ADMIN admin@pruebas.invalid; ALMACENERO almacen@pruebas.invalid; VENDEDOR vendedor.a@pruebas.invalid; clave ficticia PruebaSegura9!.', 'Abrir ingreso en tres contextos separados. || Escribir cada correo y su clave; confirmar. || Consultar opciones del rol y sesión persistida.', 'Los tres ingresan a sus opciones autorizadas con un único rol por cuenta y sesión nueva; no se convierten en cuentas multirrol.')
case('HU-AUTH-01','Credenciales rechazadas sin enumerar cuentas',[2,3], 'Variantes: correo real+claveErronea1!, nadie@pruebas.invalid+PruebaSegura9!, inactivo@pruebas.invalid+PruebaSegura9!, ambos campos vacíos.', 'Restaurar intentos antes de cada variante. || Enviar ingreso y revisar mensaje, campo de clave y cookies. || Intentar abrir una ruta protegida.', 'Las tres credenciales inválidas reciben el mismo mensaje Correo o contraseña incorrectos; no se revela qué dato falló ni el estado de cuenta. Vacíos muestran validación de campo. No hay sesión autenticada ni cambios de stock/caja.')
case('HU-AUTH-01','Permisos por URL y petición directa',[4], 'VENDEDOR intenta alta de producto; ALMACENERO intenta cobro; ADMIN intenta apertura; visitante solicita historial.', 'Guardar conteos de productos, ventas, turnos y lotes. || Solicitar las acciones ajenas por URL y POST válido con CSRF. || Comparar respuesta, cuerpo y conteos.', 'Roles ajenos reciben403 y visitante redirección al ingreso; sin datos protegidos ni mutación de negocio. La ausencia del botón no es la única protección.')
case('HU-AUTH-02','Quinto fallo, bloqueo compartido y expiración',[1,2,3], 'Cuenta vendedor.a; cuatro claves erróneas; quinta errónea a10:00:00 Lima; otra sesión; reloj10:14:59 y10:15:00.', 'Enviar cuatro fallos y comprobar que todavía no bloquea por15min. || Enviar quinto; intentar clave correcta desde otro contexto a10:14:59. || A10:15:00 ingresar correctamente. || Consultar contador.', 'Quinto fallo inicia bloqueo de15min compartido. Antes del vencimiento no ingresa e informa tiempo restante sin datos personales. Tras vencer ingresa; contador del flujo vuelve a0. No extender plazo por cada intento bloqueado.')
case('HU-AUTH-03','Salida sin borrador y conservación del turno',[1], 'Variantes independientes: ADMIN sin turno; vendedorA con turnoOPEN/apertura100 y sin líneas.', 'Abrir Salir y leer advertencia. || Confirmar. || Reabrir navegador con la cookie previa y volver a ingresar como el mismo vendedor.', 'Sesión anterior invalidada. Advertencia solo afirma turno abierto cuando existe. Turno deA sigueOPEN con esperado100; no se crea cierre. ADMIN no recibe texto que afirme turno propio inexistente.')
case('HU-AUTH-03','Cancelar o confirmar salida con venta preparada',[2,3], 'TurnoAOPEN; borrador2Leche a10; lotesA10/B10; apertura100.', 'Elegir Salir y cancelar; comprobar sesión/líneas. || Repetir Salir y confirmar descarte. || Usar Atrás/URL anterior; ingresar de nuevo comoA y luego comoB.', 'Cancelar conserva2líneas/unidades y sesión. Confirmar elimina líneas activas/descarta borrador y revoca sesión sin ventas, stock20 ni esperado100 alterados. Atrás no expone datos autenticados. A recupera turno sin borrador; B no lo ocupa ni abre paralelo.')
case('HU-AUTH-04a','Reemplazo de sesión en otro dispositivo',[1,2,3], 'FUTURO; dos navegadoresA/B para vendedor.a; sesiónA activa.', 'Ingresar enB con misma cuenta. || Solicitar datos y enviar operación desdeA. || Intentar continuar enA sin credenciales.', 'SoloB queda autorizada; A no lee ni escribe y muestra La sesión fue abierta en otro dispositivo antes de exigir ingreso. No confundir ocultar pantalla con revocar sesión. Caso no ejecutado: función futura.')
case('HU-AUTH-04b','Descarte por reemplazo sin efectos comerciales',[1,2], 'FUTURO; sesiónA con borrador2Leche, stock20 y caja100; nueva sesiónB.', 'Registrar stock/caja/ventas. || Ingresar enB provocando reemplazo deA. || Consultar borrador y repetir una petición deA.', 'Borrador anterior descartado y sin líneas cobrables; stock20,caja100,ventas0. Petición deA denegada; reemplazo no confirma ni duplica venta. Depende deAUTH04a.')
case('HU-AUTH-05','Código de recuperación válido y uso único',[1,2,3], 'FUTURO pendiente de refinamiento de seguridad; buzón ficticio; código de fixture4826 emitido10:00; claveNuevaSegura8!.', 'Solicitar recuperación en correo de prueba, usando backend de correo aislado. || A10:05 usar4826 y nueva clave. || Intentar reutilizar4826 con otra clave; probar login antiguo/nuevo.', 'Se emite un código al buzón ficticio, sin enviarlo a personas reales; primer uso cambia hash con políticaRN24 y consume código. Reutilización y clave antigua rechazadas; nueva clave ingresa. No publicar código en logs. No acredita seguridad de producción del diseño futuro.')
case('HU-AUTH-05','Caducidad y cinco códigos incorrectos',[4,5], 'FUTURO; escenarios separados:4826 emitido10:00 usado10:15:01; cinco códigos0000 incorrectos antes de caducar; sesión ya autenticada aparte.', 'Probar caducado. || Restaurar y fallar cinco veces el código; probar un sexto a10:10. || Revisar sesión autenticada y respuesta para correo inexistente.', 'Caducado muestra El código ha caducado sin cambiar clave. Cinco fallos suspenden solo recuperación15min; no bloquean la sesión existente ni revelan existencia del correo. Stock/caja intactos.')
